package br.com.equilibra.budget.api;
import br.com.equilibra.budget.application.CategoryBudgetService; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/budgets") @Tag(name="Budgets") @SecurityRequirement(name="bearerAuth") public class CategoryBudgetController { private final CategoryBudgetService service; public CategoryBudgetController(CategoryBudgetService s){service=s;} @PostMapping public ResponseEntity<BudgetDtos.Response> create(@Valid @RequestBody BudgetDtos.Create r){BudgetDtos.Response v=service.create(r);return ResponseEntity.status(HttpStatus.CREATED).body(v);} @GetMapping public List<BudgetDtos.Response> list(){return service.list();} @GetMapping("/{id:[0-9a-fA-F-]{36}}") public BudgetDtos.Response get(@PathVariable String id){return service.get(id);} @PutMapping("/{id}") public BudgetDtos.Response update(@PathVariable String id,@Valid @RequestBody BudgetDtos.Update r){return service.update(id,r);} @DeleteMapping("/{id:[0-9a-fA-F-]{36}}") public ResponseEntity<Void> delete(@PathVariable String id){service.delete(id);return ResponseEntity.noContent().build();}}
